<script setup>import{Link,usePage}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';defineProps({order:Object});const page=usePage(),money=v=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:page.props.store.currency,maximumFractionDigits:0}).format(v||0);</script><template><AppLayout><div class="container-shell max-w-3xl py-12"><div class="card p-7 text-center"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-emerald-100 text-2xl text-emerald-700">✓</div><h1 class="mt-4 text-3xl font-black">Order received</h1><p class="mt-2 text-slate-500">Keep your order number for tracking.</p><p class="mt-4 rounded-[9px] bg-slate-100 p-3 font-mono font-black">{{order.order_number}}</p><div class="mt-5 text-left"><div v-for="i in order.items" :key="i.id" class="flex justify-between border-b py-2 text-sm"><span>{{i.product_name}} × {{i.quantity}}</span><b>{{money(i.line_total)}}</b></div><div class="flex justify-between pt-4 text-lg"><b>Total</b><b>{{money(order.grand_total)}}</b></div></div><div class="mt-6 flex justify-center gap-3"><Link href="/track-order" class="btn-primary">Track order</Link><Link href="/shop" class="btn-light">Continue shopping</Link></div></div></div></AppLayout></template>
